<?php
/* Isolated, fictional coordination walkthrough. This module never opens the business database. */
declare(strict_types=1);
require_once __DIR__.'/engineering-model.php';
function field_seed():array {
 $jobs=[];foreach([['FIELD-101','Pine Ridge · sample home site',36.3,-94.1,0],['FIELD-102','Cedar Hollow · sample builder lot',36.325,-94.09,2],['FIELD-103','Oak Bend · sample driveway opportunity',36.285,-94.13,6]] as $r){
  [$id,$name,$lat,$lng,$state]=$r;$jobs[$id]=['id'=>$id,'property'=>$name,'county'=>'Benton','address'=>'Fictional property reference','apn'=>'','lat'=>$lat,'lng'=>$lng,'service'=>'Soil & site evaluation','bedrooms'=>'3','sqft'=>'Unknown','water'=>'Unknown','well_notes'=>'Confirm locations before site work','deadline'=>'','access'=>'Sample access notes: use the existing entrance.','field_state'=>$state,'field_ack'=>false,'version'=>1,'visit'=>1,'design'=>'Not submitted','design_ref'=>'','installation'=>'Not started','operation_ref'=>'','closed'=>false,'opportunity'=>$state===6,'changes'=>[],'pits'=>[],'photos'=>[],'events'=>[['actor'=>'installer','label'=>'Evaluation requested','note'=>'Fictional sample job. No appointment or permit is created.','time'=>time()-3600]],'messages'=>[]];
 }
 $now=time();$labels=['Evaluation requested','Operator headed to site','Test pits ready for evaluation','Soil evaluation recorded','Test-pit backfill authorized','Operator returning to backfill','Test pits backfilled; site cleanup recorded'];$actors=['installer','operator','operator','engineer','engineer','operator','operator'];
 foreach($jobs as &$j){$j['stage_times']=[1=>[]];$j['events']=[];for($i=0;$i<=$j['field_state'];$i++){$at=$now-7200+$i*900;$j['stage_times'][1][$i]=$at;$j['events'][]=['actor'=>$actors[$i],'label'=>$labels[$i],'note'=>'Illustrative seed timeline; not actual field activity.','time'=>$at,'visit'=>1];}}unset($j);
 return $jobs;
}
function field_role(string $role,array $allowed):void {if(!in_array($role,$allowed,true))throw new DomainException('This step belongs to '.implode(' or ',$allowed).'. Switch the sample role to continue.');}
function field_text(array $d,string $k,int $max=1500):string {return substr(trim((string)($d[$k]??'')),0,$max);}
function field_ref(array $d):string {$ref=field_text($d,'reference',200);if(strlen($ref)<4)throw new DomainException('Add the sample receipt or approval reference before recording this milestone.');return $ref;}
function field_change_index(array $job,array $d):int {foreach($job['changes'] as $i=>$c)if($c['id']===($d['change_id']??''))return $i;throw new DomainException('Choose the change request to review.');}
function field_blocked(array $j):bool {foreach($j['changes'] as $c)if(in_array($c['status'],['Review requested','Revision awaiting authority review','Additional fieldwork requested'],true))return true;return false;}
function field_apply(array $job,string $action,string $role,array $d):array {
 if(!in_array($role,['installer','operator','engineer'],true))throw new DomainException('Choose a sample role.');
 if($job['version']!==(int)($d['version']??0))throw new DomainException('This job changed. Refresh the map before saving.');
 $note=field_text($d,'note');$label='';$state=(int)$job['field_state'];
 $steps=['depart'=>[0,1,'operator','Operator headed to site'],'pits_ready'=>[1,2,'operator','Test pits ready for evaluation'],'evaluate'=>[2,3,'engineer','Soil evaluation recorded'],'authorize_backfill'=>[3,4,'engineer','Test-pit backfill authorized'],'backfill_start'=>[4,5,'operator','Operator returning to backfill'],'backfill_done'=>[5,6,'operator','Test pits backfilled; site cleanup recorded']];
 if(ns_extension_action($job,$action,$role,$d,$label)){}elseif(isset($steps[$action])){[$before,$after,$who,$label]=$steps[$action];field_role($role,[$who]);if($state!==$before)throw new DomainException('Complete the preceding field step first.');if(in_array($action,['pits_ready','evaluate','backfill_done'],true)&&$note==='')throw new DomainException('Add a short field note so the next person knows what is ready.');$job['field_state']=$after;$job['stage_times'][$job['visit']][$after]=time();
  if($action==='pits_ready'&&isset($d['pits'])&&is_array($d['pits'])){foreach(array_slice($d['pits'],0,10) as $pit){if(!is_array($pit))continue;$lat=$pit['lat']??null;$lng=$pit['lng']??null;if(!is_numeric($lat)||!is_numeric($lng)||abs((float)$lat)>90||abs((float)$lng)>180)throw new DomainException('Use valid coordinates for each test pit.');$job['pits'][]=['label'=>field_text($pit,'label',80),'lat'=>(float)$lat,'lng'=>(float)$lng,'visit'=>$job['visit']];}}
  if($action==='evaluate')$job['soil_log']=['depth'=>field_text($d,'depth',100),'bedrock'=>field_text($d,'bedrock',100),'water'=>field_text($d,'seasonal_water',100),'notes'=>$note];
  if($action==='backfill_done')foreach($job['changes'] as &$c)if($c['status']==='Additional fieldwork requested')$c['status']='Additional fieldwork completed';unset($c);
 }elseif($action==='acknowledge'){field_role($role,['installer']);if($state!==6)throw new DomainException('Wait until the test pits are backfilled.');$job['field_ack']=true;$label='Installer acknowledged completed test-pit work';
 }elseif($action==='message'){if($note==='')throw new DomainException('Write a note before sending.');$job['messages'][]=['actor'=>$role,'note'=>$note,'time'=>time()];$label='Team note added';
 }elseif($action==='opportunity'){field_role($role,['operator','installer']);$job['opportunity']=!$job['opportunity'];$label=$job['opportunity']?'Additional site services flagged':'Additional-work flag removed';
 }elseif($action==='request_change'){field_role($role,['installer']);if($note==='')throw new DomainException('Describe what needs to change or be reviewed.');$job['closed']=false;$job['changes'][]=['id'=>'CHANGE-'.bin2hex(random_bytes(4)),'type'=>field_text($d,'change_type',80)?:'Engineering review','status'=>'Review requested','request'=>$note,'response'=>'','reference'=>''];$label='Installer requested engineering review';
 }elseif($action==='review_change'){field_role($role,['engineer']);if($note==='')throw new DomainException('Record the engineering response.');$i=field_change_index($job,$d);$choice=$d['outcome']??'';
  if($choice==='fieldwork'){if(!in_array($state,[0,6],true))throw new DomainException('Finish or clarify the current field visit before requesting another.');$job['changes'][$i]['status']='Additional fieldwork requested';$job['field_state']=0;$job['field_ack']=false;$job['visit']++;$job['stage_times'][$job['visit']]=[0=>time()];}
  elseif($choice==='revision'){$job['changes'][$i]['status']='Revision awaiting authority review';$job['design']='Revision awaiting authority review';$job['operation_ref']='';$job['installation']='Not started';}
  elseif($choice==='reviewed')$job['changes'][$i]['status']='Engineering review complete — no plan revision recorded';
  else throw new DomainException('Choose the engineering next step.');
  $job['changes'][$i]['response']=$note;$label='Engineering response recorded';
 }elseif($action==='change_approval'){field_role($role,['engineer']);$i=field_change_index($job,$d);if($job['changes'][$i]['status']!=='Revision awaiting authority review')throw new DomainException('Record the revised-design review first.');$ref=field_ref($d);$job['changes'][$i]['status']='Authority approval recorded';$job['changes'][$i]['reference']=$ref;$job['design']='Construction permit recorded';$job['design_ref']=$ref;$label='Authority approval reference recorded for revision';
 }elseif($action==='submit_design'){field_role($role,['engineer']);if($state<3)throw new DomainException('Record the soil evaluation before submitting the sample application.');$job['design']='Application submitted';$job['design_ref']=field_ref($d);$label='EHP-19 application submission recorded';
 }elseif($action==='construction_permit'){field_role($role,['engineer']);if($job['design']!=='Application submitted')throw new DomainException('Record the application submission first.');$job['design_ref']=field_ref($d);$job['design']='Construction permit recorded';$label='Health authority construction permit recorded';
 }elseif($action==='install_start'){field_role($role,['installer']);if($state!==6)throw new DomainException('Complete the test-pit backfill before this sample installation starts.');if($job['design']!=='Construction permit recorded'||field_blocked($job))throw new DomainException('Wait for the recorded construction authorization and resolution of open design reviews.');$job['installation']='Installation underway';$label='Installer recorded construction start';
 }elseif($action==='install_done'){field_role($role,['installer']);if(field_blocked($job))throw new DomainException('Resolve the open design review before recording installation completion.');if($job['installation']!=='Installation underway')throw new DomainException('Record installation start first.');$job['installation']='Installation complete';$label='Installer recorded installation complete';
 }elseif($action==='inspection'){field_role($role,['installer']);if(field_blocked($job))throw new DomainException('Resolve the open design review first.');if($job['installation']!=='Installation complete')throw new DomainException('Record installation completion first.');$job['installation']='Final inspection requested';$label='Final inspection requested; authority decision pending';
 }elseif($action==='operation_approval'){field_role($role,['engineer']);if(field_blocked($job))throw new DomainException('Resolve the open design review before recording final approval.');if($job['installation']!=='Final inspection requested')throw new DomainException('Record the final inspection request first.');$job['operation_ref']=field_ref($d);$job['installation']='Operation approval recorded';$label='Health authority operation approval recorded';
 }elseif($action==='close'){field_role($role,['installer']);$archive=$d['archive_manifest']??null;
 if(!is_array($archive)||empty($archive['complete'])||empty($archive['reference'])||empty($archive['packetIds'])||!is_array($archive['files']??null))throw new DomainException('Retain the complete submission packet and final authority decision before closing.');
 $kinds=[];foreach($archive['files'] as $file){if(!is_array($file)||!preg_match('/^[a-f0-9]{64}$/',(string)($file['sha256']??''))||(int)($file['bytes']??0)<=0)throw new DomainException('A retained file manifest is incomplete.');$kinds[]=$file['kind']??'';}
 foreach(['Application record','Design/layout','Portal confirmation','Authority decision'] as $kind)if(!in_array($kind,$kinds,true))throw new DomainException('Closeout requires the application, design, submission confirmation and final authority decision.');$job['closeout_archive']=$archive;
if($state!==6||!$job['operation_ref']||field_blocked($job))throw new DomainException('Finish fieldwork and record the required approval/review outcomes before closing.');$job['closed']=true;$label='Installer closed the sample project';
 }else throw new DomainException('Unknown workflow action.');
 if(count($job['events'])>=250)throw new DomainException('Reset this sample walkthrough before adding more updates.');
 if(in_array($action,['depart','backfill_start'],true))ns_queue_update($job,'On the Way',$role,$d);if($action==='evaluate')ns_queue_update($job,'Eval Complete',$role,$d);
 $job['events'][]=['actor'=>$role,'label'=>$label,'note'=>$note,'time'=>time(),'visit'=>$job['visit']];$job['version']++;return $job;
}
function field_sync_from_projects():void {
 $projects=$_SESSION['projects']??[];
 foreach($projects as $i=>$source){
  $found=null;foreach($_SESSION['field_jobs'] as $id=>$job)if(($job['source_project_id']??'')===$source['id']){$found=$id;break;}
  if($found===null){if(count($_SESSION['field_jobs'])>=30)continue;$seedId='FIELD-'.(101+$i);if($i<3&&isset($_SESSION['field_jobs'][$seedId])&&!isset($_SESSION['field_jobs'][$seedId]['source_project_id']))$found=$seedId;else{$found='FIELD-'.substr(hash('sha256',$source['id']),0,10);$_SESSION['field_jobs'][$found]=array_values(field_seed())[0];$_SESSION['field_jobs'][$found]['id']=$found;$_SESSION['field_jobs'][$found]['stage_times']=[1=>[0=>(int)($source['created']??time())]];$_SESSION['field_jobs'][$found]['events']=[['actor'=>'installer','label'=>'Linked from sample project intake','note'=>'This is the same property record shown in the working operations view.','time'=>time()]];}}
  $j=&$_SESSION['field_jobs'][$found];if(($j['source_version']??0)<(int)$source['version']){if(isset($j['source_version']))$j['version']++;$v=$source['payload'];$j['source_project_id']=$source['id'];$j['source_version']=(int)$source['version'];foreach(['property','address','location_name','source_url','location_verified','location_basis','county','apn','bedrooms','sqft','water','well_distance','well_notes','lat','lng'] as $k)$j[$k]=$v[$k]??(in_array($k,['lat','lng'],true)?null:(in_array($k,['bedrooms','sqft','water'],true)?'Unknown':''));$j['address']=$v['address']??$v['property']??'';$j['service']=$source['contact']['service']??'Soil & site evaluation';$j['deadline']=$source['contact']['deadline']??'';$j['booking_preference']=trim(($source['contact']['requested_date']??'').' '.($source['contact']['requested_time']??''));}if(!isset($j['stage_times']))$j['stage_times']=[];if(($j['visit']??1)===1)$j['stage_times'][1][0]=(int)($source['created']??$j['events'][0]['time']);$j['source_project_id']=$source['id'];unset($j);
 }
}
function field_sync_to_project(array &$job):void {
 if(empty($job['source_project_id']))return;
 foreach($_SESSION['projects'] as &$p)if($p['id']===$job['source_project_id']){$p['payload']['field_summary']=['id'=>$job['id'],'state'=>$job['field_state'],'visit'=>$job['visit'],'design'=>$job['design'],'installation'=>$job['installation'],'opportunity'=>$job['opportunity']];$p['payload']['lat']=$job['lat'];$p['payload']['lng']=$job['lng'];$p['version']++;$job['source_version']=$p['version'];$last=end($job['events']);$_SESSION['events'][$p['id']][]=['actor'=>$last['actor'],'kind'=>$last['label'],'created'=>$last['time'],'payload'=>$last['note']];}unset($p);
}
function field_demo_handle(string $a):never {
 $_SESSION['field_jobs']??=field_seed();
 field_sync_from_projects();
 $number=101;foreach($_SESSION['field_jobs'] as &$j){if(!isset($j['site_features']))$j['site_features']=in_array($j['id'],['FIELD-101','FIELD-102','FIELD-103'],true)?ns_seed_site($j):[];$j['display_id']='FIELD-'.$number++;foreach(['source_url','location_name','well_distance','well_notes','location_basis','location_verified'] as $key)if(($j[$key]??'')==='Unknown')$j[$key]='';}unset($j);
 if($a==='field-list')reply(['jobs'=>array_values($_SESSION['field_jobs']),'demo'=>true]);
 if($_SERVER['REQUEST_METHOD']!=='POST')reply(['error'=>'Use a POST request for changes.'],405);
 $d=json_decode(file_get_contents('php://input'),true);if(!is_array($d))reply(['error'=>'Invalid request.'],422);
 try{
  if($a==='field-reset'){$_SESSION['projects']=array_values(array_filter($_SESSION['projects']??[],fn($p)=>!str_starts_with($p['id'],'FIELD-')));$_SESSION['field_jobs']=field_seed();reply(['ok'=>true]);}
  if($a==='field-create'){
   field_role((string)($d['role']??''),['installer']);if(count($_SESSION['field_jobs'])>=30)throw new DomainException('Reset your samples before adding more jobs.');
   $name=field_text($d,'property',180);$county=field_text($d,'county',100);if(!$name||!$county)throw new DomainException('Add a property reference and county.');
   $template=array_values(field_seed())[0];$id='FIELD-'.strtoupper(bin2hex(random_bytes(4)));$template['id']=$id;$template['display_id']='FIELD-'.(101+count($_SESSION['field_jobs']));$template['property']=$name;$template['county']=$county;
   foreach(['address','apn','service','bedrooms','sqft','water','well_notes','deadline','access'] as $k)$template[$k]=field_text($d,$k,500);
   foreach(['lat','lng'] as $k){$v=$d[$k]??null;$template[$k]=$v!==null&&$v!==''&&is_numeric($v)?(float)$v:null;if($template[$k]!==null&&abs($template[$k])>($k==='lat'?90:180))throw new DomainException('Use valid map coordinates.');}
   $template['stage_times']=[1=>[0=>time()]];$template['events']=[['actor'=>'installer','label'=>'Evaluation requested','note'=>'Sample request placed by the installer.','time'=>time()]];$_SESSION['projects'][]=['id'=>$id,'batch_id'=>$id,'payload'=>['property'=>$name,'county'=>$county,'apn'=>$template['apn'],'bedrooms'=>$template['bedrooms'],'water'=>$template['water'],'lat'=>$template['lat'],'lng'=>$template['lng']],'contact'=>['name'=>'Fictional installer partner','email'=>'sample@example.test','phone'=>'','service'=>$template['service'],'deadline'=>$template['deadline']],'stage'=>'Received','version'=>1,'created'=>time()];$template['source_project_id']=$id;$template['source_version']=1;field_sync_to_project($template);$_SESSION['field_jobs'][$id]=$template;reply(['job'=>$template],201);
  }
  $id=(string)($d['id']??'');if(!isset($_SESSION['field_jobs'][$id]))reply(['error'=>'Job not found.'],404);
  $_SESSION['field_jobs'][$id]=field_apply($_SESSION['field_jobs'][$id],(string)($d['action']??''),(string)($d['role']??''),$d);field_sync_to_project($_SESSION['field_jobs'][$id]);reply(['job'=>$_SESSION['field_jobs'][$id],'demo'=>true]);
 }catch(DomainException $e){reply(['error'=>$e->getMessage()],str_contains($e->getMessage(),'Refresh')?409:422);}
}
